#define NULL 0

class path_graph_edge;
class path_graph_node;

template <class T> class vector
{
    T *start;
    T *finish;
    T *end_of_storage;
public:
    typedef const T *const_iterator;
    const_iterator begin() const { return start; }
    const_iterator end() const { return finish; }
};

class stringx
{
    void *buf;
};

class path_graph_node
{
    virtual ~path_graph_node();
    char pt[16];
    void *my_region;
    unsigned short flags;
    vector<path_graph_edge *> edges;

    friend class path_graph;
};

class path_graph_edge
{
    virtual ~path_graph_edge();
    path_graph_node *nodes[2];

    friend class path_graph;
};

class path_graph
{
    stringx id;
    vector<path_graph_node *> nodes;
    vector<path_graph_edge *> edges;

public:
    virtual ~path_graph();
    bool node_in_graph(const path_graph_node *node) const;
    bool edge_in_graph(const path_graph_edge *edge) const;
    bool valid() const;
};

bool path_graph::valid() const
{
  vector<path_graph_edge *>::const_iterator i = edges.begin();
  while(i != edges.end())
  {
    if(*i != NULL)
    {
      path_graph_edge *edge = *i;

      if(edge->nodes[0] == NULL || edge->nodes[1] == NULL || edge->nodes[0] == edge->nodes[1] || !node_in_graph(edge->nodes[0]) || !node_in_graph(edge->nodes[1]))
        return(false);
    }

    ++i;
  }

  vector<path_graph_node *>::const_iterator j = nodes.begin();
  while(j != nodes.end())
  {
    if(*j != NULL)
    {
      vector<path_graph_edge *>::const_iterator i2 = (*j)->edges.begin();
      while(i2 != (*j)->edges.end())
      {
        if(*i2 != NULL)
        {
          if(!edge_in_graph((*i2)))
            return(false);
        }

        ++i2;
      }
    }

    ++j;
  }

  return true;
}
